test/refund.test.ts:
import {test,expect} from 'bun:test';
import {OrdersDb} from '../src/db';
import {refundOrder} from '../src';

test('refund uses the injected database client',()=>{
  const client = new OrdersDb('synthetic://db');
  refundOrder(client);
  expect(client.writes.length).toBe(1);
  expect(client.writes[0]).toBe('refund');
});
